func (r *meetingPolicyResource) identityOf(m meetingPolicyModel) string {
	if v := m.Identity.ValueString(); v != "" {
		return v
	}
	if v := m.ID.ValueString(); v != "" {
		return v
	}
	return ""
}

func (r *meetingPolicyResource) refresh(ctx context.Context, identity string, m *meetingPolicyModel, diags *diag.Diagnostics, reflected func(map[string]any) bool) bool {
	get := func(ctx context.Context) (map[string]any, bool, error) {
		res, gerr := r.client.CS.GetCsTeamsMeetingPolicy(ctx, cs.GetCsTeamsMeetingPolicyParams{Identity: identity})
		if gerr != nil {
			if isNotFound(gerr) {
				return nil, false, nil
			}
			return nil, false, gerr
		}
		o := firstObject(res.Value)
		return o, o != nil, nil
	}
	obj, present, err := resourcex.LoadUntil(ctx, consistency.Config{}, get, reflected)
	if err != nil {
		diags.AddError("Get-MeetingPolicy failed", err.Error())
		return false
	}
	if !present {
		return false
	}
	readMeetingPolicy(ctx, obj, m)
	return true
}

